package local.tvmorph.tv;
import android.content.*;import android.security.keystore.*;import java.security.*;import javax.crypto.*;import javax.crypto.spec.*;import java.io.*;import java.util.*;import org.json.*;
final class IptvStore{
 private JSONArray orderSource;private final Map<String,JSONArray> orderedRows=new HashMap<>();
 private synchronized JSONArray ordered(JSONArray source,String mode)throws Exception{if(mode.equals("recent"))mode="newest";if(!Arrays.asList("az","za","oldest","newest").contains(mode))return source;if(orderSource!=source){orderSource=source;orderedRows.clear();}JSONArray found=orderedRows.get(mode);if(found!=null)return found;String[] names=new String[source.length()];long[] dates=new long[source.length()];for(int i=0;i<names.length;i++){JSONObject row=source.getJSONObject(i);names[i]=row.optString("name");dates[i]=row.optLong("added",0);}JSONArray result=new JSONArray();for(int index:CatalogOrder.indices(names,dates,mode))result.put(source.getJSONObject(index));orderedRows.put(mode,result);return result;}
 private final Context context;private Xtream client;private final Map<String,JSONArray> cache=new LinkedHashMap<>(),categoryCache=new HashMap<>();private final Map<String,JSONObject> detailCache=new LinkedHashMap<>();private final Map<String,Long> loadedAt=new HashMap<>(),retryAt=new HashMap<>();private final Set<String> refreshing=new HashSet<>();private final java.util.concurrent.ExecutorService updater=java.util.concurrent.Executors.newSingleThreadExecutor();private long cacheAt;private int revision;private final Object[] catalogLocks={new Object(),new Object(),new Object(),new Object(),new Object(),new Object(),new Object(),new Object()};private Object catalogLock(String kind){return catalogLocks[(kind.hashCode()&0x7fffffff)%catalogLocks.length];}private final CatalogDisk disk;
 private static IptvStore instance;static synchronized IptvStore get(Context c){if(instance==null)instance=new IptvStore(c);return instance;}
 IptvStore(Context c){context=c==null?null:c.getApplicationContext();disk=new CatalogDisk(context,this::key);if(context!=null)M3uPlaylist.localFiles=this::openPlaylistFile;}
 private File playlistFile(String id)throws IOException{if(id==null||!id.matches("[a-f0-9-]{36}"))throw new IOException("Invalid playlist file ID");return new File(context.getFilesDir(),"playlist-"+id+".enc");}
 private InputStream openPlaylistFile(String id)throws Exception{FileInputStream source=new FileInputStream(playlistFile(id));try{byte[] iv=new byte[12];new DataInputStream(source).readFully(iv);Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,iv));return new CipherInputStream(source,cipher);}catch(Exception error){source.close();throw error;}}
 synchronized JSONObject importPlaylistText(String text,String name)throws Exception{
  byte[] bytes=text.getBytes("UTF-8");if(bytes.length>2097152||!text.replace("\uFEFF","").trim().startsWith("#EXTM3U"))throw new IOException("Use a valid M3U file up to 2 MB.");
  File temporary=File.createTempFile("iptv-phone-",".m3u",context.getCacheDir());try{try(FileOutputStream out=new FileOutputStream(temporary)){out.write(bytes);}return importPlaylist(android.net.Uri.fromFile(temporary),name);}finally{temporary.delete();}
 }
 synchronized JSONObject importPlaylist(android.net.Uri uri,String name)throws Exception{
  if(uri==null||!"content".equals(uri.getScheme()))throw new IOException("اختار ملف M3U من متصفح الملفات.");long used=0;File[] files=context.getFilesDir().listFiles();if(files!=null)for(File file:files)if(file.getName().startsWith("playlist-")&&file.getName().endsWith(".enc"))used+=file.length();if(used>192L*1024*1024)throw new IOException("مساحة ملفات القوائم المحفوظة ممتلئة. استخدم رابط الاشتراك.");
  String id=UUID.randomUUID().toString();File destination=playlistFile(id);try{Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,key());try(InputStream source=context.getContentResolver().openInputStream(uri);FileOutputStream file=new FileOutputStream(destination)){if(source==null)throw new IOException("تعذر فتح الملف.");file.write(cipher.getIV());try(CipherOutputStream encrypted=new CipherOutputStream(file,cipher)){byte[] bytes=new byte[16384];int n;long total=0,deadline=System.nanoTime()+90000000000L;while((n=source.read(bytes))!=-1){total+=n;if(total>96L*1024*1024||total+used>192L*1024*1024)throw new IOException("حجم ملف M3U أكبر من الحد الآمن.");if(Thread.currentThread().isInterrupted()||System.nanoTime()>deadline)throw new IOException("انتهت مهلة استيراد الملف.");encrypted.write(bytes,0,n);}}}
  return connect(new JSONObject().put("type","m3u").put("server","https://local-playlist.invalid/"+id+".m3u").put("localFileId",id).put("name",name==null||name.trim().isEmpty()?"M3U file":name.trim().substring(0,Math.min(120,name.trim().length()))));
  }catch(Exception error){boolean saved=false;try{JSONArray accounts=savedAccounts();for(int i=0;i<accounts.length();i++)if(id.equals(accounts.getJSONObject(i).optString("localFileId"))){saved=true;break;}}catch(Exception ignored){}if(!saved)destination.delete();throw error;}
 }
 private javax.crypto.SecretKey key()throws Exception{KeyStore store=KeyStore.getInstance("AndroidKeyStore");store.load(null);String alias="tvmorph.iptv";if(!store.containsAlias(alias)){KeyGenerator g=KeyGenerator.getInstance("AES","AndroidKeyStore");g.init(new KeyGenParameterSpec.Builder(alias,KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());g.generateKey();}return (javax.crypto.SecretKey)store.getKey(alias,null);}
 private void save(JSONObject data)throws Exception{saveFile("iptv-account",data);}
 private void saveFile(String name,JSONObject data)throws Exception{Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,key());try(FileOutputStream out=context.openFileOutput(name+".tmp",Context.MODE_PRIVATE)){out.write(cipher.getIV());out.write(cipher.doFinal(data.toString().getBytes("UTF-8")));}try{java.nio.file.Files.move(new File(context.getFilesDir(),name+".tmp").toPath(),new File(context.getFilesDir(),name).toPath(),java.nio.file.StandardCopyOption.REPLACE_EXISTING,java.nio.file.StandardCopyOption.ATOMIC_MOVE);}catch(java.nio.file.AtomicMoveNotSupportedException e){java.nio.file.Files.move(new File(context.getFilesDir(),name+".tmp").toPath(),new File(context.getFilesDir(),name).toPath(),java.nio.file.StandardCopyOption.REPLACE_EXISTING);}}
 private JSONObject readFile(String name)throws Exception{File file=new File(context.getFilesDir(),name);if(!file.exists())throw new IOException("لا يوجد اشتراك خاص محفوظ. أضف بياناته مرة واحدة.");byte[] bytes=new byte[(int)file.length()];try(DataInputStream in=new DataInputStream(new FileInputStream(file))){in.readFully(bytes);}if(bytes.length<28)throw new IOException("Invalid saved IPTV profile");Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,Arrays.copyOfRange(bytes,0,12)));return new JSONObject(new String(cipher.doFinal(Arrays.copyOfRange(bytes,12,bytes.length)),"UTF-8"));}
 private Xtream load()throws Exception{if(client!=null)return client;File file=new File(context.getFilesDir(),"iptv-account");if(!file.exists()){File personal=new File(context.getFilesDir(),"iptv-personal");if(personal.exists()){JSONObject saved=readFile("iptv-personal");client=new Xtream(saved);save(saved);return client;}JSONObject free=new JSONObject().put("type","m3u").put("publicMode",true).put("publicSource","arabic").put("server",M3uPlaylist.PUBLIC_URL).put("profileId","public-iptvorg-arabic").put("name",UiSettings.text(context,"القنوات الناطقة بالعربية","Arabic-language channels")).put("live",true).put("vod",false).put("series",false);client=new Xtream(free);return client;}byte[] bytes=new byte[(int)file.length()];try(DataInputStream in=new DataInputStream(new FileInputStream(file))){in.readFully(bytes);}Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,Arrays.copyOfRange(bytes,0,12)));client=new Xtream(new JSONObject(new String(cipher.doFinal(Arrays.copyOfRange(bytes,12,bytes.length)),"UTF-8")));return client;}
 synchronized void importPhoneProfile(JSONObject payload)throws Exception{if(UiSettings.prefs(context).getBoolean("iptvPhoneProfileMigrated",false))return;try{if(!load().config.optBoolean("publicMode"))return;}catch(Exception missing){}if(payload==null||payload.optString("server").isEmpty())return;JSONObject clean=new JSONObject(payload.toString());if(clean.optString("profileId").isEmpty())clean.put("profileId",UUID.randomUUID().toString());Xtream next=new Xtream(clean);save(clean);refresh();client=next;}
 private boolean sameAccount(JSONObject a,JSONObject b){return a.optString("type","xtream").equals(b.optString("type","xtream"))&&a.optString("server").equals(b.optString("server"))&&a.optString("username").equals(b.optString("username"))&&a.optString("mac").equals(b.optString("mac"));}
 private void addAccount(JSONArray rows,JSONObject value)throws Exception{if(value==null||value.optBoolean("publicMode")||value.optString("server").isEmpty())return;JSONObject copy=new JSONObject(value.toString());for(int i=0;i<rows.length();i++)if(sameAccount(rows.getJSONObject(i),copy)||(!copy.optString("profileId").isEmpty()&&copy.optString("profileId").equals(rows.getJSONObject(i).optString("profileId")))){String id=rows.getJSONObject(i).optString("profileId");if(!id.isEmpty())copy.put("profileId",id);rows.put(i,copy);return;}if(copy.optString("profileId").isEmpty())copy.put("profileId",UUID.randomUUID().toString());if(rows.length()>=100)throw new IOException("يمكن حفظ حتى 100 اشتراك.");rows.put(copy);}
 private JSONArray savedAccounts()throws Exception{JSONArray rows=new JSONArray();try{JSONArray saved=readFile("iptv-accounts").optJSONArray("items");if(saved!=null)for(int i=0;i<saved.length();i++)addAccount(rows,saved.getJSONObject(i));}catch(Exception ignored){}try{addAccount(rows,readFile("iptv-personal"));}catch(Exception ignored){}try{addAccount(rows,load().config);}catch(Exception ignored){}return rows;}
 private JSONObject safeAccount(JSONObject p,String active)throws Exception{return new JSONObject().put("id",p.optString("profileId")).put("name",p.optString("name","My TV")).put("type",p.optString("type","xtream")).put("localFile",!p.optString("localFileId").isEmpty()).put("active",p.optString("profileId").equals(active)).put("subscription",p.optJSONObject("subscription")!=null?p.getJSONObject("subscription"):new JSONObject());}
 synchronized JSONObject accountEdit(String id)throws Exception{JSONArray rows=savedAccounts();for(int i=0;i<rows.length();i++)if(id.equals(rows.getJSONObject(i).optString("profileId")))return new JSONObject(rows.getJSONObject(i).toString());throw new IOException("Saved subscription not found");}
 synchronized JSONObject accounts()throws Exception{JSONArray rows=savedAccounts(),out=new JSONArray();String active=client!=null?client.config.optString("profileId"):"";for(int i=0;i<rows.length();i++)out.put(safeAccount(rows.getJSONObject(i),active));if(rows.length()>0&&!new File(context.getFilesDir(),"iptv-accounts").exists())saveFile("iptv-accounts",new JSONObject().put("items",rows));return new JSONObject().put("items",out);}
 synchronized JSONObject removePlaylistFile(String accountId)throws Exception{
  return removeSavedAccount(accountId,true);
 }
 synchronized JSONObject removeAccount(String accountId)throws Exception{return removeSavedAccount(accountId,false);}
 synchronized boolean matchesSavedAccount(JSONObject profile,String accountId)throws Exception{
  if(profile==null)return false;
  JSONObject normalized=profile.optString("type").equals("portal")?PortalSource.normalize(profile):profile.optString("type").equals("m3u")?M3uPlaylist.normalize(profile):XtreamCredentials.normalize(profile);
  JSONArray rows=savedAccounts();for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);if(accountId.equals(row.optString("profileId")))return sameAccount(row,normalized);}return false;
 }
 private JSONObject removeSavedAccount(String accountId,boolean fileOnly)throws Exception{
  if(accountId==null||accountId.isEmpty())throw new IOException("Select a saved account.");
  JSONArray rows=savedAccounts(),kept=new JSONArray();JSONObject removed=null;
  for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);if(accountId.equals(row.optString("profileId")))removed=row;else kept.put(row);}
  if(removed==null)throw new IOException("The saved account was not found.");
  if(fileOnly&&removed.optString("localFileId").isEmpty())throw new IOException("Only imported local playlist files can be deleted here.");
  File file=removed.optString("localFileId").isEmpty()?null:playlistFile(removed.getString("localFileId"));
  boolean current=false;try{current=accountId.equals(load().config.optString("profileId"))||!load().config.optBoolean("publicMode")&&sameAccount(removed,load().config);}catch(Exception ignored){}
  saveFile("iptv-accounts",new JSONObject().put("items",kept));
  // A legacy phone-vault backup must not resurrect a deliberately deleted account.
  UiSettings.prefs(context).edit().putBoolean("iptvPhoneProfileMigrated",true).apply();
  try{if(accountId.equals(readFile("iptv-personal").optString("profileId"))||sameAccount(removed,readFile("iptv-personal")))context.deleteFile("iptv-personal");}catch(Exception ignored){}
  if(current){
   // Switch locally: deleting an expired/offline provider must never require authentication.
   if(kept.length()>0){JSONObject next=kept.getJSONObject(0);save(next);saveFile("iptv-personal",next);client=new Xtream(next);}
   else{context.deleteFile("iptv-account");context.deleteFile("iptv-personal");client=null;}
   refresh();
  }
  boolean referenced=false;for(int i=0;i<kept.length();i++)if(removed.optString("localFileId").equals(kept.getJSONObject(i).optString("localFileId")))referenced=true;
  boolean fileRemoved=file==null||referenced||!file.exists()||file.delete();
  return new JSONObject().put("removed",true).put("currentRemoved",current).put("fileRemoved",fileRemoved).put("accounts",accounts().getJSONArray("items"));
 }
 synchronized JSONObject accountInfo()throws Exception{return accountInfo(new JSONObject());}
 synchronized JSONObject accountInfo(JSONObject input)throws Exception{JSONObject cfg=null;String id=input.optString("accountId");if(!id.isEmpty()){JSONArray saved=savedAccounts();for(int i=0;i<saved.length();i++)if(id.equals(saved.getJSONObject(i).optString("profileId")))cfg=saved.getJSONObject(i);if(cfg==null)throw new IOException("الاشتراك المحفوظ غير موجود.");}else cfg=load().config;Xtream c=new Xtream(cfg);JSONObject info=c.auth().put("checkedAt",System.currentTimeMillis()/1000);cfg.put("subscription",info);if(client!=null&&cfg.optString("profileId").equals(client.config.optString("profileId"))){client.config.put("subscription",info);save(client.config);if(!cfg.optBoolean("publicMode"))saveFile("iptv-personal",cfg);}if(!cfg.optBoolean("publicMode")){JSONArray rows=savedAccounts();addAccount(rows,cfg);saveFile("iptv-accounts",new JSONObject().put("items",rows));}return new JSONObject().put("profileId",cfg.optString("profileId")).put("name",cfg.optString("name","My TV")).put("subscription",info);}
 synchronized JSONObject connect(JSONObject input)throws Exception{JSONArray rows=savedAccounts();JSONObject payload=input;if(!input.optString("editAccountId").isEmpty()){payload=accountEdit(input.getString("editAccountId"));for(Iterator<String> it=input.keys();it.hasNext();){String k=it.next();if(!k.equals("editAccountId")&&!k.equals("profileId")&&!k.equals("localFileId"))payload.put(k,input.get(k));}}else if(!input.optString("accountId").isEmpty()){payload=null;for(int i=0;i<rows.length();i++)if(rows.getJSONObject(i).optString("profileId").equals(input.optString("accountId"))){payload=rows.getJSONObject(i);break;}if(payload==null)throw new IOException("الاشتراك المحفوظ غير موجود.");}else if(input.optBoolean("restorePersonal",false))payload=readFile("iptv-personal");payload=new JSONObject(payload.toString());if(input.optBoolean("useHttp")&&payload.optString("type").equals("xtream")&&payload.optString("server").startsWith("https://"))payload.put("server","http://"+payload.optString("server").substring(8));payload=payload.optString("type").equals("portal")?PortalSource.normalize(payload):payload.optString("type").equals("m3u")?M3uPlaylist.normalize(payload):XtreamCredentials.normalize(payload);String profile=payload.optBoolean("publicMode")?"public-iptvorg-"+payload.optString("publicSource","arabic"):payload.optString("profileId",UUID.randomUUID().toString());if(!payload.optBoolean("publicMode"))for(int i=0;i<rows.length();i++)if(sameAccount(rows.getJSONObject(i),payload)){profile=rows.getJSONObject(i).optString("profileId",profile);break;}boolean existing=false;for(int i=0;i<rows.length();i++)if(sameAccount(rows.getJSONObject(i),payload)||(!input.optString("editAccountId").isEmpty()&&rows.getJSONObject(i).optString("profileId").equals(input.optString("editAccountId")))||(!input.optString("accountId").isEmpty()&&rows.getJSONObject(i).optString("profileId").equals(input.optString("accountId")))){existing=true;break;}if(!payload.optBoolean("publicMode")&&!existing&&rows.length()>=2&&!PlusAccess.verified(context))throw new IOException("الحسابان الشخصيان متاحان مجانًا. فعّل Plus لإضافة حساب ثالث؛ القنوات المجانية لا تُحسب. Two personal accounts are free; a third requires Plus.");payload.put("profileId",profile);IptvConnection.Result connection;try{connection=IptvConnection.open(payload);}catch(Exception error){if(!payload.optBoolean("publicMode")){JSONObject pending=new JSONObject(payload.toString());pending.put("subscription",new JSONObject().put("status","Pending").put("checkedAt",System.currentTimeMillis()/1000));addAccount(rows,pending);saveFile("iptv-accounts",new JSONObject().put("items",rows));}String reason=ProviderFailure.message(error);throw new IOException((reason==null||reason.trim().isEmpty()?"تعذر الاتصال بالمزوّد.":reason)+" تم حفظ الاشتراك في الحسابات المحفوظة؛ افتحه وحاول الربط مرة أخرى.");}Xtream next=connection.client;payload=next.config;payload.put("profileId",profile);next.config.put("profileId",profile);JSONObject details=new JSONObject(connection.auth.toString()).put("checkedAt",System.currentTimeMillis()/1000);payload.put("subscription",details);next.config.put("subscription",details);if(!payload.optBoolean("publicMode",false)){addAccount(rows,payload);saveFile("iptv-personal",payload);}if(rows.length()>0)saveFile("iptv-accounts",new JSONObject().put("items",rows));save(payload);refresh();client=next;return summary().put("connected",true);}
 synchronized JSONObject summary()throws Exception{Xtream c=load();return new JSONObject().put("configured",true).put("type",c.config.optString("type","xtream")).put("publicMode",c.config.optBoolean("publicMode",false)).put("publicSource",c.config.optString("publicSource","")).put("hasPersonal",!c.config.optBoolean("publicMode",false)||new File(context.getFilesDir(),"iptv-personal").exists()).put("viewerName",UiSettings.prefs(context).getString("viewerName","Family")).put("viewerId",UiSettings.prefs(context).getString("viewerId","default")).put("profileId",c.config.optString("profileId","default")).put("name",c.config.optString("name","My TV")).put("live",c.config.optBoolean("live",true)).put("vod",c.config.optBoolean("vod",true)).put("series",c.config.optBoolean("series",true)).put("subscription",c.config.optJSONObject("subscription")!=null?c.config.getJSONObject("subscription"):new JSONObject()).put("accounts",accounts().getJSONArray("items"));}
 private void check(Xtream c,int version)throws IOException{if(client!=c||revision!=version)throw new IOException("المكتبة اتغيرت. جرّب فتح القسم تاني.");}
 private void expire(){if(System.currentTimeMillis()-cacheAt>300000L){detailCache.clear();cacheAt=System.currentTimeMillis();}}
  private String pageVersion(Xtream c,String viewer,String kind,String category,String search,String order,int page,long at){
   if(at<=0)return "";
   JSONArray token=new JSONArray();
   token.put(revision);token.put(c.config.optString("profileId","default"));token.put(viewer);
   token.put(kind);token.put(category);token.put(search);token.put(order);token.put(page);token.put(at);
   return token.toString();
  }
  JSONObject list(JSONObject payload)throws Exception{
   String kind=payload.optString("kind","live"),category=payload.optString("category",""),search=payload.optString("search","").toLowerCase(Locale.ROOT);Xtream c;int version;JSONArray all;String epoch;
   if(!search.isEmpty()&&!kind.equals("episode")&&!payload.optBoolean("scopeCategory"))category="";
   String key=kind+":"+category,order=kind.equals("episode")?"provider":payload.optString("order");
   int page=Math.max(0,payload.optInt("page",0)),pageSize=Math.max(1,Math.min(60,payload.optInt("pageSize",60)));
   synchronized(this){c=load();version=revision;expire();all=cache.get(key);epoch=disk.epoch();}
   if(!Arrays.asList("live","vod","series","episode").contains(kind))throw new IOException("Invalid content type");if(!kind.equals("episode")&&!c.config.optBoolean(kind,true))throw new IOException("القسم ده غير مفعّل في إعدادات الاشتراك.");
   int previewLimit=Math.max(0,Math.min(200,payload.optInt("limit",0)));
   if(previewLimit>0&&all==null&&search.isEmpty()&&!kind.equals("episode")&&(order.equals("provider")||order.isEmpty())){
    JSONObject first=c.preview(kind,category,previewLimit);JSONArray rows=first.getJSONArray("rows");int total=first.optInt("total",rows.length());
    int from=Math.min(page*pageSize,rows.length());JSONArray items=new JSONArray();
    for(int i=from;i<Math.min(rows.length(),from+pageSize);i++)items.put(decorate(rows.getJSONObject(i),c));
    synchronized(this){check(c,version);}return new JSONObject().put("items",items).put("total",total).put("page",page).put("hasMore",first.optBoolean("hasMore")||(page+1)*pageSize<total).put("totalExact",first.optBoolean("totalExact",true)).put("seasons",new JSONArray()).put("catalogVersion","");}
   synchronized(this){check(c,version);
    String viewer=UiSettings.prefs(context).getString("viewerId","default"),known=pageVersion(c,viewer,kind,category,search,order+"|size="+pageSize,page,loadedAt.getOrDefault(key,0L));
    if(!known.isEmpty()&&known.equals(payload.optString("catalogVersion")))return new JSONObject().put("unchanged",true);}
   if(all==null&&!category.isEmpty()&&!kind.equals("episode"))synchronized(this){check(c,version);JSONArray full=cache.get(kind+":");if(full!=null){JSONArray sub=new JSONArray();for(int i=0;i<full.length();i++){JSONObject row=full.getJSONObject(i);if(category.equals(row.optString("category")))sub.put(row);}all=sub;loadedAt.put(key,loadedAt.getOrDefault(kind+":",0L));}}
   if(all==null)synchronized(catalogLock(key)){synchronized(this){check(c,version);all=cache.get(key);}if(all==null){all=disk.read(c.config.optString("profileId"),epoch,key);long at=disk.savedAt(c.config.optString("profileId"),epoch,key);if(all==null){all=kind.equals("episode")?c.episodes(category):c.list(kind,category);at=System.currentTimeMillis();disk.save(c.config.optString("profileId"),epoch,key,all);}synchronized(this){check(c,version);rememberCatalog(key,all,at);}}}
   updateLater(c,version,epoch,key,kind,category,false);
   all=ordered(all,kind.equals("episode")?"provider":payload.optString("order"));
  JSONArray seasons=new JSONArray();if(kind.equals("episode")){java.util.TreeSet<String> seasonNames=new java.util.TreeSet<>((a,b)->{try{return Integer.compare(Integer.parseInt(a),Integer.parseInt(b));}catch(Exception e){return a.compareTo(b);}});for(int i=0;i<all.length();i++)seasonNames.add(all.getJSONObject(i).optString("season","1"));for(String season:seasonNames)seasons.put(season);String selected=payload.optString("season");if(!selected.isEmpty()){JSONArray filtered=new JSONArray();for(int i=0;i<all.length();i++)if(selected.equals(all.getJSONObject(i).optString("season","1")))filtered.put(all.getJSONObject(i));all=filtered;}}
   int start=page*pageSize,total=0;JSONArray items=new JSONArray();
  if(search.isEmpty()){total=all.length();for(int i=start;i<Math.min(total,start+pageSize);i++)items.put(decorate(all.getJSONObject(i),c));}
  else for(int i=0;i<all.length();i++){JSONObject item=all.getJSONObject(i);if(item.optString("name").toLowerCase(Locale.ROOT).contains(search)){if(total>=start&&items.length()<pageSize)items.put(decorate(item,c));total++;}}
   String token;synchronized(this){check(c,version);token=pageVersion(c,UiSettings.prefs(context).getString("viewerId","default"),kind,category,search,order+"|size="+pageSize,page,loadedAt.getOrDefault(key,0L));}return new JSONObject().put("items",items).put("total",total).put("page",page).put("hasMore",(page+1)*pageSize<total).put("seasons",seasons).put("catalogVersion",token);
 }

 private void rememberCatalog(String key,JSONArray rows,long at){cache.remove(key);cache.put(key,rows);loadedAt.put(key,at);long size=0;for(JSONArray value:cache.values())size+=value.length()*1024L;while(cache.size()>1&&(cache.size()>6||size>24*1024*1024L)){String oldest=cache.keySet().iterator().next();size-=cache.remove(oldest).length()*1024L;loadedAt.remove(oldest);}}
 private void updateLater(Xtream c,int version,String epoch,String key,String kind,String category,boolean categories){
  final String taskKey=version+":"+key;synchronized(this){long now=System.currentTimeMillis();if(client!=c||revision!=version||now-loadedAt.getOrDefault(key,0L)<CatalogDisk.FRESH||now-retryAt.getOrDefault(key,0L)<60000||!refreshing.add(taskKey))return;retryAt.put(key,now);}
  updater.execute(()->{try{JSONArray rows=categories?c.categories(kind):kind.equals("episode")?c.episodes(category):c.list(kind,category);synchronized(this){check(c,version);if(categories){categoryCache.put(kind,rows);loadedAt.put(key,System.currentTimeMillis());}else rememberCatalog(key,rows,System.currentTimeMillis());disk.save(c.config.optString("profileId"),epoch,key,rows);}}catch(Exception ignored){}finally{synchronized(this){refreshing.remove(taskKey);}}});
 }
 private JSONObject decorate(JSONObject source,Xtream c)throws Exception{JSONObject item=new JSONObject(source.toString());item.put("icon",c.rememberImage(item.optString("kind"),item.optString("id"),item.optString("icon")));int position=0;if(UiSettings.prefs(context).getBoolean("resume",true)&&Arrays.asList("vod","episode").contains(item.optString("kind")))position=PlaybackMemory.get(context,PlaybackMemory.key(PlaybackMemory.account(context,c.config.optString("profileId","default")),item.optString("kind"),item.optString("id")));item.put("resumeMs",position);if(Arrays.asList("vod","episode").contains(item.optString("kind"))){String memoryKey=PlaybackMemory.key(PlaybackMemory.account(context,c.config.optString("profileId","default")),item.optString("kind"),item.optString("id"));item.put("durationMs",PlaybackMemory.duration(context,memoryKey));}return item;}
 synchronized JSONObject history()throws Exception{return progress(PlaybackHistory.entries(context,load().config.optString("profileId","default")));}
 synchronized JSONObject progress(JSONArray items)throws Exception{Xtream c=load();JSONArray output=new JSONArray();if(items!=null)for(int i=0;i<Math.min(200,items.length());i++){JSONObject item=items.optJSONObject(i);if(item!=null)output.put(decorate(item,c));}return new JSONObject().put("items",output);}
 synchronized void refresh(){orderSource=null;orderedRows.clear();revision++;if(client!=null)client.clearMetadata();cache.clear();categoryCache.clear();detailCache.clear();loadedAt.clear();retryAt.clear();refreshing.clear();cacheAt=System.currentTimeMillis();disk.reset();}
 JSONObject categories(String kind)throws Exception{if(!Arrays.asList("live","vod","series").contains(kind))throw new IOException("Invalid category type");Xtream c;int version;JSONArray rows;synchronized(this){c=load();version=revision;expire();rows=categoryCache.get(kind);}String epoch=disk.epoch(),key="categories:"+kind;if(rows==null)synchronized(catalogLock(key)){synchronized(this){check(c,version);rows=categoryCache.get(kind);}if(rows==null){rows=disk.read(c.config.optString("profileId"),epoch,key);long at=disk.savedAt(c.config.optString("profileId"),epoch,key);if(rows==null){rows=c.categories(kind);at=System.currentTimeMillis();disk.save(c.config.optString("profileId"),epoch,key,rows);}synchronized(this){check(c,version);categoryCache.put(kind,rows);loadedAt.put(key,at);}}}updateLater(c,version,epoch,key,kind,"",true);return new JSONObject().put("items",rows);}
 JSONObject details(JSONObject item)throws Exception{Xtream c;int version;JSONObject value;String key=item.optString("kind")+":"+item.optString("id");synchronized(this){c=load();version=revision;expire();value=detailCache.get(key);}if(value==null){value=c.details(item);synchronized(this){check(c,version);detailCache.put(key,value);while(detailCache.size()>30)detailCache.remove(detailCache.keySet().iterator().next());}}synchronized(this){check(c,version);}return decorate(value,c);}
 JSONObject epg(String id)throws Exception{Xtream c;int version;synchronized(this){c=load();version=revision;}JSONObject result=c.epg(id);synchronized(this){check(c,version);}return result;}
 synchronized String originalStream(JSONObject item)throws Exception{return load().originalStream(item);}
 String resolvePlayback(JSONObject item)throws Exception{Xtream c;int version;synchronized(this){c=load();version=revision;}String result=c.resolveStream(item);synchronized(this){check(c,version);}return result;}
 synchronized String playback(JSONObject item)throws Exception{return load().stream(item);}
 synchronized void clear(){if(context!=null){context.deleteFile("iptv-account");context.deleteFile("iptv-personal");context.deleteFile("iptv-accounts");}client=null;refresh();}
}

